head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
scwin.vScrenID = "ULDSTF70030_N.xml"; //화면ID
scwin.v_SaveKind = ""; //신규,수정 구분
scwin.vBzProcsNo = ""; //업무처리번호
//var vIsurCd = "";					//발행기관코드
//var vIsurNm = "";					//발행회사명
scwin.vIsuCd = ""; // 종목코드
scwin.vDscYn = ""; // 공시여부
scwin.vListBzTpCd = "788"; //상장업무구분코드 (삭제시 필요) - 로그처리방지용


//Transaction 처리코드
scwin.TR_JOB;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//2017-02-13 KBoY FileSizeLimit 30MB		
scwin.canUploadFile = function() {
    var maxFileSize = 1024 * 1024 * 30; //30MB		
    var mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};


/********************************************** 
 * 함수명 : fn_filedown(bzProcsNo, attachFileNo) 
 * Params : bzProcsNo:업무처리번호 , attachFileNo: 번호
 * 설명    : 파일 다운로드 (gubun = 311)
 ***********************************************/
scwin.fn_filedown = function(bzProcsNo, attachSeq) {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&ATTACH_SEQ=" + attachSeq + "&gubun=311";
};


/********************************************** 
 * 함수명 : fn_file_sync() 
 * 설명    :  첨부파일 리스트 불러오기 
 ***********************************************/
scwin.fn_file_sync = function() {
    var url = "/digital/DigitalListinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=DigitalFileList&inputMessageId=DIGITAL_FILE_OUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_fileList.DataID = encodeURI(url);
    dts_fileList.Reset();
};



/********************************************** 
 * 함수명 : fn_CheckForm(kind)
 * Params : kind( N:신규, U:수정)
 * 설명    : Form Validation Check
 ***********************************************/
scwin.fn_CheckForm = function(kind) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(edt_CHG_LIST_DD) == "") {
        $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }

    //Check Max Length
    if ($c.stf.getObjectValue(txb_ISU_NM2) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_ISU_NM2))) > 1) {
            if (!$c.stf.checkMaxLength(txb_ISU_NM2, 80, "한글종목명")) return false;
        }
    } else if ($c.stf.getObjectValue(txb_ISU_NM2) == "") {
        $c.win.alert("[한글종목명]을 입력하세요.");
        txb_ISU_NM2.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_ABBRV2) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_ISU_ABBRV2))) > 1) {
            if (!$c.stf.checkMaxLength(txb_ISU_ABBRV2, 40, "한글종목약명")) return false;
        }
    } else if ($c.stf.getObjectValue(txb_ISU_ABBRV2) == "") {
        $c.win.alert("[한글종목약명]을 입력하세요.");
        txb_ISU_ABBRV2.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_ENG_NM2) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_ISU_ENG_NM2))) > 1) {
            if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM2, 80, "영문종목명")) return false;
        }
    } else if ($c.stf.getObjectValue(txb_ISU_ENG_NM2) == "") {
        $c.win.alert("[영문종목명]을 입력하세요.");
        txb_ISU_ENG_NM2.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_ENG_ABBRV2) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_ISU_ENG_ABBRV2))) > 1) {
            if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV2, 40, "영문종목약명")) return false;
        }
    } else if ($c.stf.getObjectValue(txb_ISU_ENG_ABBRV2) == "") {
        $c.win.alert("[영문종목약명]을 입력하세요.");
        txb_ISU_ENG_ABBRV2.focus();
        return false;
    }


    // 병합 비율
    if (txb_DIGITAL_SECU_CONSLDT_RTO.getValue() == "") {
        txb_DIGITAL_SECU_CONSLDT_RTO.setValue("0");
    }

    // 분할 비율
    if (txb_DIGITAL_SECU_SPLIT_RTO.getValue() == "") {
        txb_DIGITAL_SECU_SPLIT_RTO.setValue("0");
    }

    // 증권 수
    if (txb_LIST_QTY2.getValue() == "") {
        txb_LIST_QTY2.setValue("0");
    }

    //신규인 경우에만 체크하도록 함
    if (scwin.v_SaveKind == "N") {
        if (vCurDate >= $c.stf.getObjectValue(edt_CHG_LIST_DD)) {
            $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
            edt_CHG_LIST_DD.focus();
            return false;
        }
    }

    // 변경사유 길이체크 
    if (!$c.stf.checkMaxLength(txa_CHG_RSN, 2000, "변경사유")) return false;
    return true;
};



/********************************************** 
 * 함수명 : fn_SetFormField()
 * 설명    : 신규저장,수정하기 전 Form Field Value에 대하여 2바이트 체크 
 *             현업의 미입력에서도 '-' 하이픈을 입력하는 경우가 많아 처리함
 ***********************************************/
scwin.fn_SetFormField = function() {
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_ISU_NM2))) == 1) {
        $c.stf.setObjectValue(txb_ISU_NM2, "");
    }
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_ISU_ABBRV2))) == 1) {
        $c.stf.setObjectValue(txb_ISU_ABBRV2, "");
    }
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_ISU_ENG_NM2))) == 1) {
        $c.stf.setObjectValue(txb_ISU_ENG_NM2, "");
    }
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_ISU_ENG_ABBRV2))) == 1) {
        $c.stf.setObjectValue(txb_ISU_ENG_ABBRV2, "");
    }
};




/********************************************** 
 * 함수명 : fn_dupCheck()
 * 설명    : 종목 중복날짜 체크
 ***********************************************/
scwin.fn_dupCheck = function() {
    var chgDd = $c.stf.getObjectValue(edt_CHG_LIST_DD);
    var isNotDup = true;
    dts_DupChk.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=DIGITAL_CODE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.digital.nm_chglist.select.list_check" + "&{P}param01=" + scwin.vIsuCd + "&{P}param02=" + chgDd;
    dts_DupChk.DataID = encodeURI(url);
    dts_DupChk.reset();
    if (dts_DupChk.getTotalRow() > 0) {
        if (scwin.vBzProcsNo != dts_DupChk.getCellData(1, "BZ_PROCS_NO")) {
            isNotDup = false;
            $c.win.alert("동일한 날짜에 변경상장 지정된 종목이 존재합니다.");
        }
    }
    return isNotDup;
};


/********************************************** 
 * 함수명 : fn_select_isur()
 * 설명    :  신규 내역 조회
 ***********************************************/
scwin.fn_select_isur = function() {
    var url = "/digital/DigitalListinvstg.do?method=listDigitalNameChangeDetailNewRequest";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_ISU_CD=" + scwin.vIsuCd; // 종목코드

    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();

    //vIsurCd= dts_Isu.NameValue(1,"ISUR_CD");
    //vIsurNm = dts_Isu.NameValue(1,"ISUR_NM");

};





/********************************************** 
 * 함수명 : fn_select_isur_detail()
 * 설명    : 업무처리번호에 대한 상세내역 조회
 ***********************************************/
scwin.fn_select_isur_detail = function() {
    var url = "/digital/DigitalListinvstg.do?method=listDigitalNameChangeDetailUpdateRequest";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo; // 업무처리번호
    url += "&SRCH_ISU_CD=" + scwin.vIsuCd; // 종목코드


    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();


    //	vIsurCd= dts_Isu.NameValue(1,"ISUR_CD");
    //	vIsurNm = dts_Isu.NameValue(1,"ISUR_NM");

};







/********************************************** 
 * 함수명 : fn_save_nm_isur_new()
 * 설명    : 변경상장 > 종목명변경/증권분할.병합입력 및 세부내역 > 신규저장
 ***********************************************/
scwin.fn_save_nm_isur_new = function() {
    //if (fn_CheckForm(v_SaveKind) == false)
    //	return;

    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm(scwin.v_SaveKind) && scwin.fn_dupCheck()) {
        //Transaction 처리전 안내문구
        if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;

        // 저장 처리
        var vScrenId = "SCREN_ID=" + scwin.vScrenID;
        var vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        var vSrvMethod = "&method=insertNmChngDtl";
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo); //업무처리번호 새로 지정

        trs_Save.Action = "/digital/DigitalListinvstg.do?" + vScrenId + vScrenTpId + vSrvMethod;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Isu,I:pFile=dts_fileList)";
        trs_Save.Parameters = "TRS_IDX=" + TR_JOB_INSERT + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISU_CD=" + scwin.vIsuCd + ",ISUR_CD=" + dts_Isu.getCellData(1, "ISUR_CD") + ",ACPT_NO=" + js_emp_no + ",LD_MKT_TP_CD=1" + ",TRANSTR_EMP_NO=" + js_emp_no;
        trs_Save.Post();
    }
};



/********************************************** 
 * 함수명 : fn_save_nm_isur_update()
 * 설명    : 변경상장 > 종목명변경  > 상세보기 > 수정
 ***********************************************/
scwin.fn_save_nm_isur_update = function() {
    scwin.TR_JOB = 'U';
    if (($c.cp.isModified(dts_Isu) == false) && ($c.cp.isModified(dts_fileList) == false)) {
        $c.win.alert("수정내역이 존재하지 않습니다.");
        return;
    }
    if (scwin.fn_CheckForm(scwin.v_SaveKind) && scwin.fn_dupCheck()) {
        //Transaction 처리전 안내문구
        if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
        if ($c.ut.trim(txb_LIST_QTY2.getValue()) == "") {
            txb_LIST_QTY2.setValue("0");
        }
        var vScrenId = "SCREN_ID=" + scwin.vScrenID;
        var vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        var vSrvMethod = "&method=updateNmChngDtl";
        trs_Save.Action = "/digital/DigitalListinvstg.do?" + vScrenId + vScrenTpId + vSrvMethod;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Isu,I:pFile=dts_fileList)";
        trs_Save.Parameters = "TRS_IDX=" + TR_JOB_UPDATE + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISU_CD=" + scwin.vIsuCd + ",ISUR_CD=" + dts_Isu.getCellData(1, "ISUR_CD") + ",LD_MKT_TP_CD=1" + ",ACPT_NO=" + js_emp_no + ",TRANSTR_EMP_NO=" + js_emp_no;
        trs_Save.Post();
    }
};



/********************************************** 
 * 함수명 : fn_save_nm_isur_delete
 * 설명    : 변경상장 > 종목명 변경 > 상세보기 > 삭제
 ***********************************************/
scwin.fn_save_nm_isur_delete = function() {
    if (scwin.vBzProcsNo == "") {
        $c.win.alert("삭제 정보(업무처리번호)가 없습니다.");
        return;
    }


    // 공시 체크
    if (!$c.lcd.fn_check_delete_discls(dts_BzProcsNo, scwin.vBzProcsNo)) return;
    scwin.TR_JOB = 'D';

    //Transaction 처리전 안내문구
    if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    var vScrenId = "SCREN_ID=" + scwin.vScrenID;
    var vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    var vSrvMethod = "&method=deleteNmChngDtl";
    trs_Save.Action = "/digital/DigitalListinvstg.do?" + vScrenId + vScrenTpId + vSrvMethod;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + TR_JOB_DELETE + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISU_CD=" + scwin.vIsuCd + ",ISUR_CD=" + dts_Isu.getCellData(1, "ISUR_CD") + ",LD_MKT_TP_CD=1" + ",ACPT_NO=" + js_emp_no + ",TRANSTR_EMP_NO=" + js_emp_no;
    trs_Save.Post();
};




/********************************************** 
 * 함수명 : fn_checkModifyDts()
 * 설명    : 안내문작성 시, 수정사항 체크
 ***********************************************/
scwin.fn_checkModifyDts = function() {
    var rtn = false;
    if ($c.cp.isModified(dts_Isu) == false) {
        rtn = true;
    } else {
        $c.win.alert("변경된 내용이 있습니다. [수정] 후 진행하세요.");
        rtn = false;
    }
    return rtn;
};


/********************************************** 
 * 함수명 : fn_dscl()
 * 설명    : 수량변경 > 발행 및 상장내역 > 안내문 작성
 ***********************************************/
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.fn_dscl = async function() {
    if ($c.stf.getObjectValue(edt_CHG_LIST_DD) == "") {
        $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    var cCtnt = "";
    if (scwin.fn_checkModifyDts() == false) {
        return;
    }
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2) {
        arr[0] = "69565A";
        arr[1] = scwin.vBzProcsNo;
        arr[2] = dts_Isu.getCellData(1, "ISUR_CD"); // 상장신청인 발행코드
        arr[3] = '1';
        //arr[4] = fn_getNmChgDisclsCtnt(); //ctnt
        arr[5] = $c.stf.getObjectValue(txb_ISU_ABBRV); //add  title

        var sDate = scwin.dateForm($c.stf.getObjectValue(edt_CHG_LIST_DD));
        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
        $c.stf.CopyDataSet(dts_Isu, param_dts_mst);

        // 파라미터 ds 만 값 변경
        param_dts_isu.setCellData(param_dts_isu.getFocusedRowIndex(), "CHG_LIST_DD", sDate);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "CHG_LIST_DD", sDate);
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 750;
    var hgt = 820;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "변경상장 종목명변경/증권분할·분할 안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;

    //안내문팝업 후 '닫기'나 '안내문전송' 후에 Popup Close 및 Parent Refresh 함
    $c.frame.path("../").fn_list_nm_chglist_sync();
};


/********************************************** 
 * 함수명 : fn_getNmChgDisclsCtnt()
 * 설명    : 안내문작성 서식 (수량변경)
 ***********************************************/
scwin.fn_getNmChgDisclsCtnt = function() {
    var vIsuNmChg = ""; // 종목명변경 Y/N
    var vIsuQtyChg = ""; // 수량변경 Y/N

    if ($c.stf.getObjectValue(txb_ISU_NM2).length > 0 || $c.stf.getObjectValue(txb_ISU_ABBRV2).length > 0 || $c.stf.getObjectValue(txb_ISU_ENG_NM2).length > 0 || $c.stf.getObjectValue(txb_ISU_ENG_ABBRV2).length > 0) {
        vIsuNmChg = "Y";
    } else {
        vIsuNmChg = "N";
    }
    if (($c.stf.getObjectValue(txb_DIGITAL_SECU_CONSLDT_RTO).length > 0 || $c.stf.getObjectValue(txb_DIGITAL_SECU_SPLIT_RTO).length > 0 || $c.stf.getObjectValue(txb_LIST_QTY2).length > 0) &&
        ($c.stf.getObjectValue(txb_DIGITAL_SECU_CONSLDT_RTO) > 0 || $c.stf.getObjectValue(txb_DIGITAL_SECU_SPLIT_RTO) > 0 || $c.stf.getObjectValue(txb_LIST_QTY2) > 0)) {
        vIsuQtyChg = "Y";
    } else {
        vIsuQtyChg = "N";
    }
    var vCtnt;
    vCtnt = "[공시제목] 신종증권 변경상장";
    vCtnt += "\r\n\r\n";
    vCtnt += "[본문내용]";
    vCtnt += "\r\n\r\n";
    vCtnt += "◎ " + $c.stf.getObjectValue(txb_ISU_NM) + " 변경상장";
    vCtnt += "\r\n\r\n";
    vCtnt += "\r\n\r\n";
    vCtnt += "1. 변경내역  ";
    if (vIsuNmChg == "Y") {
        vCtnt += "\r\n\r\n";
        vCtnt += " - 한글종목명";
        vCtnt += "\r\n\r\n";
        vCtnt += "변경전 : " + $c.stf.getObjectValue(txb_ISU_NM) + " (약명 : " + $c.stf.getObjectValue(txb_ISU_ABBRV) + ")";
        vCtnt += "\r\n\r\n";
        vCtnt += "변경후 : " + $c.stf.getObjectValue(txb_ISU_NM2) + " (약명 : " + $c.stf.getObjectValue(txb_ISU_ABBRV2) + ")";
        vCtnt += "\r\n\r\n";
        vCtnt += " - 영문종목명";
        vCtnt += "\r\n\r\n";
        vCtnt += "변경전 : " + $c.stf.getObjectValue(txb_ISU_ENG_NM) + " (약명 : " + $c.stf.getObjectValue(txb_ISU_ENG_ABBRV) + ")";
        vCtnt += "\r\n\r\n";
        vCtnt += "변경후 : " + $c.stf.getObjectValue(txb_ISU_ENG_NM2) + " (약명 : " + $c.stf.getObjectValue(txb_ISU_ENG_ABBRV2) + ")";
    }
    if (vIsuQtyChg == "Y") {
        vCtnt += "\r\n\r\n";
        vCtnt += " - 병합·분할";
        vCtnt += "\r\n\r\n";
        vCtnt += "병합비율 : " + txb_DIGITAL_SECU_CONSLDT_RTO.getValue();
        vCtnt += "\r\n\r\n";
        vCtnt += "분할비율 : " + txb_DIGITAL_SECU_SPLIT_RTO.getValue();
        vCtnt += "\r\n\r\n";
        vCtnt += "변경전 상장수량 : " + txb_LIST_QTY.getValue();
        vCtnt += "\r\n\r\n";
        vCtnt += "변경후 상장수량 : " + txb_LIST_QTY2.getValue();
    }
    vCtnt += "\r\n\r\n";
    vCtnt += "2. 변경 사유 : " + txa_CHG_RSN.getText();
    vCtnt += "\r\n\r\n";
    vCtnt += "5. 변경상장일 : " + scwin.dateForm($c.stf.getObjectValue(edt_CHG_LIST_DD));
    vCtnt += "\r\n\r\n";
    return vCtnt;
};


/********************************************** 
 * 함수명 : dateForm()
 * 설명    : 년월일 포맷 맞춤 (안내문 작성에서 사용)
 ***********************************************/
scwin.dateForm = function(pStr) {
    var str = "";
    if (pStr == "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년 " + pStr.substring(4, 6) + "월 " + pStr.substring(6, 8) + "일";
    }
    return str;
};


/********************************************** 
 * 함수명 : fn_parentRefresh()
 * 설명    : Parent 화면 Refresh()
 ***********************************************/
scwin.fn_parentRefresh = function() {
    //Parent 신청내역 화면 Refresh
    var parentWin = $c.frame.path("../");
    parentWin.fn_list_nm_chglist_sync();
};
scwin.btn_QtyIsuClose_onclick = async function() {
    //닫기(수량변경)
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    //Form onload event

    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    var parentWin = $c.frame.path("../");

    //Transaction 구분: 신규(N), 수정(U), 삭제(D)
    scwin.v_SaveKind = parentWin.vIsuChgKind;

    // 업무처리번호
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    // 종목코드
    scwin.vIsuCd = parentWin.clickIsuCd;
    // 공시여부
    scwin.vDscYn = parentWin.clickDisclsYn;
    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 


    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save_nm_isur_new); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_save_nm_isur_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_save_nm_isur_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성


    if (scwin.vBzProcsNo == '') {
        // 신규 정보 조회
        scwin.fn_select_isur();
    } else {
        // 상세 정보 조회
        scwin.fn_select_isur_detail();
    }
};
scwin.trs_Save_OnSuccess = async function() {
    //저장메세지, 부모화면 Refresh, 화면 닫기
    $c.lcd.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_select_isur_detail();
    }
    //frame.CloseFrame();

};
scwin.trs_Save_OnFail = function() {
    $c.lcd.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
